  bricks.forEach(b => { if (b.alive) { ctx.fillStyle = ACCENT; ctx.globalAlpha = 0.55 + (b.y / 200); ctx.fillRect(b.x, b.y, 44, 16); } });
  ctx.globalAlpha = 1; ctx.fillStyle = ACCENT; ctx.fillRect(paddle, H - 16, PW, 8);
  ctx.beginPath(); ctx.arc(ball.x, ball.y, 6, 0, 7); ctx.fill();
  if (over) { ctx.fillStyle = '#8b8d98'; ctx.font = '600 16px system-ui'; ctx.textAlign = 'center'; ctx.fillText(bricks.every(b => !b.alive) ? 'You cleared it! Tap to play again' : 'Game over — tap to play again', W / 2, 180); }
  document.getElementById('score').textContent = score;
