  if (!alive) { ctx.fillStyle = '#fff'; ctx.font = '600 16px system-ui'; ctx.textAlign = 'center'; ctx.fillText('Game over — tap to fly again', W / 2, H / 2); }
  document.getElementById('score').textContent = score;
