  s = s.replace(/\bbeata\s+horse\b/gi, (all) => mark(all, 'beat a horse')).replace(/\bbeat\s+ahorse\b/gi, (all) => mark(all, 'beat a horse')).replace(/\bduck beta\b/gi, (all) => mark(all, 'duck beat'));
