function gibberish(s) {
  const w = s.toLowerCase().replace(/[^a-z ]/g, '').trim(); if (!w) return false;
  const parts = w.split(/\s+/);
  if (parts.length === 1 && /^[a-z]$/.test(w) && w !== 'a' && w !== 'i' && w !== 'k' && w !== 'u') return true;
  if (/^(?:([a-z])\1{2,})$/.test(w.replace(/ /g, '')) && w !== 'kkk') return true;
  const rows = ['qwertyuiop', 'asdfghjkl', 'zxcvbnm'];
  const flat = w.replace(/ /g, '');
  if (flat.length >= 3 && rows.some(r => r.indexOf(flat) >= 0 || r.indexOf(flat.slice(0, 4)) >= 0 && flat.length <= 6 && !COMMON.has(flat))) return true;
  if (/^(?:[a-z]{2,4})\1+$/.test(flat) && !COMMON.has(flat)) return true;                     // "sdfsdf"
  if (parts.length <= 2 && parts.every(p => p.length <= 3 && !/[aeiouy]/.test(p)) && !parts.every(p => COMMON.has(p) || LISTED.has(p) || SHORT_OK.has(p))) return true;
  return false;
}
