  { const bare = t.match(/^(?:hey|yo|ok|okay)?\s*(?:oxygen|chatgpt|chatbbt|siri|alexa|bot|ai)[,!.\s]*$/i); if (bare) return done('social', ['Yes? What can I do for you?', 'I am here. What would you like?']); }

