    if (/\b(you|your|yourself)\b/.test(norm) && !genericYou(norm) && !/\b(i|my|me)\b/.test(norm) && !an.words.some(t => t.pos === 'name') && !/\b(tips?|recommendations?|suggestions?|advice|ideas?|information|info|examples?|resources|insights?|facts|details) (on|about|for|regarding|of)\b/.test(norm)) { say(fill(pick(W.SELF_TALK[selfKind(norm)], ctx.aiTexts.slice(-3)), { maker: W.MAKER })); return done('self'); }
    const tail = an.words.slice(Math.max(0, an.words.filter(t => t.kind !== 'poss').length - norm.split(' ').length));
    const keep = tail.filter(t => !(t.pos === 'wh' || t.pos === 'aux' || t.pos === 'modal' || t.pos === 'pron' || t.kind === 'poss' || /^(a|an|my|your|our|please|tell|way|ways|get|go)$/.test(t.low)));
