    const howTo = /^(how|where|when|what|which|who|do|does|did|can|could|should|is|are)\b.*\b(i|we|my|me|you|one|someone|people)\b/.test(norm) || /^how (do|does|did|can|to|is|are|should|would)\b/.test(norm);
    const why = /^(why|what (happens|causes|makes))\b/.test(norm);
