    for (let i = 0, run = []; i <= keep.length; i++) { if (i < keep.length && named.indexOf(keep[i]) >= 0) run.push(keep[i].pos === 'n' && keep[i].lemma && run.length === 0 && named.indexOf(keep[i + 1]) < 0 ? keep[i].lemma : keep[i].low); else { if (run.length && (!about || run.length >= about.split(' ').length)) about = run.join(' '); run = []; } }
    if (about) { const nm = (' ' + norm + ' ').match(new RegExp(' ' + about.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ' (\\d+|i{1,3}|iv|one|two|three)\\b')); if (nm) about += ' ' + nm[1]; }      // "world war 2": the number belongs to the name
    if (about && ctx.lastTopic && (' ' + norm + ' ').indexOf(' ' + String(ctx.lastTopic).toLowerCase() + ' ') >= 0) about = ctx.lastTopic;   // still the same subject
    const ofThing = about && !personal && ((qtypeOf(norm) && qtypeOf(norm) !== 'who') || /^(what|which|where|when) (do|does|did|can|could) /.test(norm));   // "when was einstein born", "what do dogs eat": read about the subject, then find the sentence
    const doing = keep.filter(t => t.pos === 'v' && t.lemma && !/^(do|get|go|be|have|make|use|can|will|need|want|know|think|try|let|put|take)$/.test(t.lemma)).map(t => t.lemma)[0];   // "wash", "cook", "tie": the question is about DOING it
