    if (await search(q1, qtypeOf(norm), why && !personal, focusQ, practical)) return done('search', about);
    if (q1 !== query && await search(query, qtypeOf(norm), false, focusQ, practical)) return done('search', about);
    if (about && about !== q1 && about !== query && /^who [a-z]+ (?:the )?/.test(norm) && await search(about, 'who', false, focusQ, false)) return done('search', about);   // "who wrote hamlet": read about Hamlet, then find who wrote it
    if (about) meta.topic = about;
    if (meta.partial) { say(pick(['I found a page about {t}, but it does not answer that question.', 'My search led to {t}, and nothing there says how to do it.', 'The closest that I found was {t}, which does not cover this.'], ctx.aiTexts.slice(-2)).replace('{t}', meta.partial.title)); say(pick(['A guide or a forum for it will know better than I do.', 'This needs a source more detailed than the ones I can read.'])); delete meta.partial; return done('unsure', about); }
    { const ws = an.words.filter(t => t.kind === 'w'); let run = [], best = [];
      ws.forEach(t => { if ((t.pos === 'name' || t.status === 'unknown') && !t.closed) run.push(t); else { if (run.length > best.length) best = run; run = []; } }); if (run.length > best.length) best = run;
      if (best.length >= 2 && best.some(t => t.status === 'unknown')) { say(pick(['I have nothing about {n}.', 'I do not know who {n} is.'], ctx.aiTexts.slice(-2)).replace('{n}', best.map(t => cap(t.raw)).join(' '))); say('I searched the web and found nothing about them. If you tell me who they are, I will remember it.'); return done('unsure'); } }
    say(pick(S.unsure, ctx.aiTexts.slice(-2)));
    if (unknownWords.length) say(fill(pick(S.unknownWord), { word: unknownWords[0] }));
    if (!THINK && meshKnown(2)) return done('unsure');
    if (THINK) { say('I searched for "' + q1 + '"' + (q1 !== query ? ' and "' + query + '"' : '') + ', and nothing I read answers it.'); return done('unsure'); }
