  if (firstW && firstW.pos === 'v' && firstW.feat === 'base' && !greeted) { say(pick(S.cannotDo, ctx.aiTexts.slice(-2))); return done('cannot'); }
  const onlyUnknown = unknownWords.length && an.words.every(t => t.status === 'unknown' || t.closed);
  if (!greeted && !onlyUnknown) say(pick(S.ack, ctx.aiTexts.slice(-2)));
  if (unknownWords.length) say(fill(pick(S.unknownWord), { word: unknownWords[0] }));
  if (onlyUnknown) { say(pick(['Could you explain what it means? I will remember it.', 'If you tell me what it means, I will add it to my memory.'])); meta.ask = { kind: 'meaning', word: unknownWords[0].toLowerCase() }; return done('unsure'); }
