  if (c2.listed && c2.listed.length > 1) { meta.list = c2.listed.map(x => String(x).toLowerCase()); c2.listed = null; } else delete meta.list;
  const nouns = an.words.filter(t => t.kind === 'w' && !t.closed && t.lemma && (t.pos === 'n' || t.pos === 'name') && t.status !== 'unknown' && !GENERIC_NOUN.test(t.low));
