      const askText = (args && args.text) || '';
      const buildThing = /\b(?:website|site|web ?page|landing page|portfolio|game|app|calculator|program|script|function|class|bot)\b/i;
      const askedToBuild = (/\b(?:code|build|make|create|write|program|design)\b/i.test(askText) || /^\s*(?:an?|my)\s+[\w' -]{0,40}\b(?:game|website|site|app|calculator|landing page|portfolio)\b\s+(?:where|that|with|for|in which)\b/i.test(askText))
        && buildThing.test(askText) && !/\?\s*$/.test(askText) && !/\b(?:story|poem|essay|song|letter|speech)\b/i.test(askText);
